/**
 * Shell-safe quoting utility for Terraform CLI command generation.
 *
 * Uses POSIX single-quote escaping: wraps the value in single quotes
 * and escapes any embedded single quotes via the '\'' idiom
 * (end quote, backslash-literal-quote, restart quote).
 *
 * @module state/shell-quote
 * @generated by code-quality-improver (TASK-DATA-005)
 */

/**
 * Wraps an address in single quotes for shell safety.
 *
 * Embedded single quotes are escaped using the POSIX '\'' technique:
 *   "it's"  ->  'it'\''s'
 *
 * This prevents shell injection when addresses contain unexpected characters.
 */
export function shellQuote(addr: string): string {
  // Replace each ' with '\'' — ends the current single-quoted string,
  // adds an escaped literal single quote, then restarts quoting.
  const escaped = addr.replace(/'/g, "'\\''");
  return `'${escaped}'`;
}
